package com.taskflow.service; import com.taskflow.dto.ProjectDtos.*; import com.taskflow.entity.*; import com.taskflow.exception.*; import com.taskflow.repository.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.*;
@Service public class ProjectService{final ProjectRepository ps;final UserRepository us;final TaskRepository ts;public ProjectService(ProjectRepository p,UserRepository u,TaskRepository t){ps=p;us=u;ts=t;}User user(String e){return us.findByEmail(e).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));}Project p(String e,Long id){return ps.findByIdAndOwnerId(id,user(e).getId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Project not found"));}ProjectResponse d(Project p){return new ProjectResponse(p.getId(),p.getName(),p.getDescription());}public List<ProjectResponse> all(String e){return ps.findAllByOwnerIdOrderByIdDesc(user(e).getId()).stream().map(this::d).toList();}public ProjectResponse get(String e,Long id){return d(p(e,id));}public ProjectResponse create(String e,ProjectRequest r){Project p=new Project();p.setName(r.name());p.setDescription(r.description());p.setOwner(user(e));return d(ps.save(p));}public ProjectResponse update(String e,Long id,ProjectRequest r){Project p=p(e,id);p.setName(r.name());p.setDescription(r.description());return d(ps.save(p));}public void delete(String e,Long id){Project p=p(e,id);ts.deleteAllByProjectId(id);ps.delete(p);}}
